 "content": "def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    bg=max({v for row in grid for v in row},key=lambda c:sum(row.count(c) for row in grid))
    points={(r,c) for r in range(h) for c in range(w) if grid[r][c]!=bg}; seen=set()
    for start in points:
        if start in seen: continue
        col=grid[start[0]][start[1]]; st=[start]; seen.add(start); comp=set()
        while st:
            r,c=st.pop(); comp.add((r,c))
            for dr,dc in ((0,1),(0,-1),(1,0),(-1,0)):
                q=(r+dr,c+dc)
                if q in points and q not in seen and grid[q[0]][q[1]]==col: seen.add(q); st.append(q)
        r0=min(r for r,c in comp);r1=max(r for r,c in comp);c0=min(c for r,c in comp);c1=max(c for r,c in comp)
        edge={(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1) if r in (r0,r1) or c in (c0,c1)}
        if r1-r0<2 or c1-c0<2 or not edge<=comp: continue
        fill=7 if len(comp)==len(edge) else 2
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                if grid[r][c]==bg: out[r][c]=fill
    return out
